export const getProtocolTargetAddress = (protocolName: string, poolAddress?: string): string => {
  if (poolAddress && poolAddress.startsWith("0x") && poolAddress.length === 42) {
    return poolAddress;
  }
  const match = Object.keys(PROTOCOL_TARGET_ADDRESSES).find((key) =>
    protocolName.toLowerCase().includes(key.toLowerCase())
  );
  if (match) {
    return PROTOCOL_TARGET_ADDRESSES[match];
  }
  return "0x5Ff40197C83C3A2705ba912333Cf1a37BA249eB7";
};

